import os
import random
import string
from typing import List

# This generator produces a valid filesystem path to an existing file.
# It constructs paths within common temporary directories and ensures
# the referenced file exists by choosing from pre-existing OS files
# (like /etc/hosts, /etc/passwd on Unix) or well-known Windows files.
# If none are available, it falls back to current script's directory entries
# or '.' to refer to the current directory.

def _candidate_paths_unix() -> List[str]:
    return [
        "/etc/hosts",
        "/etc/passwd",
        "/etc/services",
        "/etc/resolv.conf",
        "/bin/sh",
        "/usr/bin/env",
        "/proc/cpuinfo",
        "/proc/meminfo",
        "/var/log/syslog",
        "/var/log/messages",
        "/etc/ssl/cert.pem",
    ]

def _candidate_paths_windows() -> List[str]:
    sysroot = os.environ.get("SystemRoot", r"C:\\Windows")
    return [
        os.path.join(sysroot, "System32", "drivers", "etc", "hosts"),
        os.path.join(sysroot, "System32", "notepad.exe"),
        os.path.join(sysroot, "win.ini"),
        os.path.join(sysroot, "System32", "cmd.exe"),
    ]

def _existing_paths_from_dir(base: str, max_pick: int = 10) -> List[str]:
    out: List[str] = []
    try:
        for name in os.listdir(base):
            p = os.path.join(base, name)
            if os.path.isfile(p):
                out.append(p)
            if len(out) >= max_pick:
                break
    except Exception:
        pass
    return out

def _gather_candidates() -> List[str]:
    cands: List[str] = []
    if os.name == "nt":
        cands.extend(_candidate_paths_windows())
    else:
        cands.extend(_candidate_paths_unix())

    # Common temp and config locations
    tmp_dirs = [
        os.getenv("TMPDIR"), os.getenv("TMP"), os.getenv("TEMP"),
        "/tmp" if os.name != "nt" else None,
        os.path.expanduser("~"),
        os.getcwd(),
    ]
    for d in tmp_dirs:
        if d and os.path.isdir(d):
            cands.extend(_existing_paths_from_dir(d, max_pick=20))

    # Python install and standard files
    try:
        import sys
        cands.append(sys.executable)
    except Exception:
        pass

    # Deduplicate while preserving order
    seen = set()
    uniq = []
    for p in cands:
        if p and p not in seen:
            seen.add(p)
            uniq.append(p)
    # Keep only existing files (directories are allowed too, in case the consumer permits dirs)
    final = [p for p in uniq if os.path.exists(p)]
    # As last resort, include current directory
    if not final:
        final.append(".")
    return final

def _maybe_make_relative(rnd: random.Random, path: str) -> str:
    # Randomly convert to relative by prefix stripping common roots
    if rnd.random() < 0.4:
        try:
            cwd = os.getcwd()
            rel = os.path.relpath(path, cwd)
            return rel
        except Exception:
            return path
    return path

def _maybe_add_components(rnd: random.Random, path: str) -> str:
    # Add harmless redundant components like ./ or resolve .. to keep valid
    components = []
    sep = os.sep
    # Prepend ./ occasionally
    if rnd.random() < 0.3 and not path.startswith("." + sep):
        path = "." + sep + path
    # Insert a few ./ segments inside
    if rnd.random() < 0.3:
        parts = path.split(sep)
        if len(parts) > 2:
            idx = rnd.randrange(1, len(parts))
            parts.insert(idx, ".")
            path = sep.join(parts)
    # Normalize occasionally to ensure still valid
    if rnd.random() < 0.5:
        try:
            path = os.path.normpath(path)
        except Exception:
            pass
    return path

def _encode_path(path: str) -> bytes:
    # Encode as UTF-8 with surrogateescape to preserve bytes on POSIX
    return (path + "\0").encode("utf-8", errors="surrogateescape")

def generate(seed: int) -> bytes:
    rnd = random.Random(seed)
    candidates = _gather_candidates()
    # Weight certain interesting files higher
    weights = []
    for p in candidates:
        w = 1.0
        base = os.path.basename(p).lower()
        if base in {"hosts", "passwd", "services", "resolv.conf", "cmd.exe", "notepad.exe"}:
            w = 3.0
        elif os.path.isdir(p):
            w = 0.5
        weights.append(w)
    # Choose a candidate
    if candidates:
        choice = rnd.choices(candidates, weights=weights, k=1)[0]
    else:
        choice = "."

    # Randomly tweak into relative form and add redundant components
    choice = _maybe_make_relative(rnd, choice)
    choice = _maybe_add_components(rnd, choice)

    # Ensure final path exists; if tweaking broke it, fall back
    if not os.path.exists(choice):
        # Try original without tweaks
        original_candidates = _gather_candidates()
        choice = rnd.choice(original_candidates) if original_candidates else "."

    # Limit path length to keep total buffer under 4096 bytes
    if len(choice) > 4000:
        choice = choice[:4000]

    return _encode_path(choice)

import random
import string
from typing import List

# Data type: free-form text (null-terminated C string when consumed)
# Target stubs consume FUZZ_PARAM_STR() for:
#  - iperf_set_test_extra_data: extra data tag (may be NULL, but fuzzer toggles that itself)
#  - warning: message string
# We generate interesting yet valid UTF-8/byte strings. Avoid embedded NULs.

MAX_TOTAL = 4096

PRINTABLE = string.ascii_letters + string.digits + string.punctuation + " "
WHITES = " \t\r\n\v\f"
CTRL_NO_NUL = bytes([c for c in range(1, 32) if c != 0x00]).decode('latin1')  # 0x01..0x1F without NUL

UNICODE_SAMPLES = [
    "\u2713",  # ✓
    "✨", "🚀", "数据", "тест", "π", "Δ", "ñ", "ø", "ü", "€", "𝒜", "𐍈"
]

BASE64_CHARS = string.ascii_letters + string.digits + "+/="
HEX_CHARS = string.hexdigits


def rand_printable(r: random.Random, n: int) -> str:
    return ''.join(r.choice(PRINTABLE) for _ in range(n))


def rand_base64(r: random.Random, n: int) -> str:
    return ''.join(r.choice(BASE64_CHARS) for _ in range(n))


def rand_hex(r: random.Random, n: int) -> str:
    return ''.join(r.choice(HEX_CHARS) for _ in range(n))


def rand_unicode(r: random.Random, n: int) -> str:
    parts: List[str] = []
    for _ in range(n):
        choice = r.randint(0, 4)
        if choice == 0:
            parts.append(r.choice(UNICODE_SAMPLES))
        elif choice == 1:
            # random BMP codepoint excluding surrogates and control area below 0x20
            # choose either from 0x20..0xD7FF or 0xE000..0xFFFD
            if r.random() < 0.5:
                cp = r.randint(0x20, 0xD7FF)
            else:
                cp = r.randint(0xE000, 0xFFFD)
            parts.append(chr(cp))
        elif choice == 2:
            parts.append(rand_printable(r, 1))
        elif choice == 3:
            parts.append(r.choice(WHITES + CTRL_NO_NUL))
        else:
            parts.append(rand_base64(r, 1))
    s = ''.join(parts)
    return s.replace('\x00', '')


def make_jsonish(r: random.Random) -> str:
    key_count = r.randint(1, 6)
    items = []
    for _ in range(key_count):
        key = rand_printable(r, r.randint(1, 10)).strip()
        key = key.replace('"', "'")
        vtype = r.randint(0, 4)
        if vtype == 0:
            val_inner = rand_unicode(r, r.randint(0, 16)).replace('"', "'")
            val = '"' + val_inner + '"'
        elif vtype == 1:
            val = str(r.randint(0, 10**9))
        elif vtype == 2:
            val = str(r.random())
        elif vtype == 3:
            val = 'true' if r.choice([True, False]) else 'false'
        else:
            val = 'null'
        items.append('"' + key + '": ' + val)
    return '{' + ', '.join(items) + '}'


def make_pathlike(r: random.Random) -> str:
    parts = []
    depth = r.randint(1, 6)
    for _ in range(depth):
        seg = rand_printable(r, r.randint(1, 8)).strip()
        seg = seg.replace('/', '_')
        parts.append(seg or 'x')
    prefix = r.choice(['', '/', './', '../', '~/', 'C:\\', ''])
    return prefix + '/'.join(parts)


def make_message_variants(r: random.Random) -> List[str]:
    variants: List[str] = []
    variants.append("")
    variants.append("ok")
    variants.append("warning: something happened")
    variants.append(make_jsonish(r))
    variants.append(make_pathlike(r))
    variants.append(rand_base64(r, r.randint(8, 64)))
    variants.append(rand_hex(r, r.randint(8, 64)))
    variants.append(rand_unicode(r, r.randint(8, 64)))
    variants.append(''.join(r.choice(WHITES + CTRL_NO_NUL) for _ in range(r.randint(4, 32))))
    para_len = r.randint(128, 1024)
    variants.append(rand_unicode(r, para_len))
    return variants


def assemble_buffer(r: random.Random) -> bytes:
    variants = make_message_variants(r)
    r.shuffle(variants)
    blob = "\n".join(variants)
    b = blob.encode('utf-8', errors='replace')
    if len(b) > MAX_TOTAL:
        b = b[:MAX_TOTAL]
        try:
            blob2 = b.decode('utf-8', errors='ignore')
            b = blob2.encode('utf-8')
        except Exception:
            pass
    return b


def generate(seed: int) -> bytes:
    r = random.Random(seed)
    return assemble_buffer(r)
